 ('За рекламу +10', ["За рекламу +{}", "Watch an ad +{}", "Für Werbung +{}", "Por anuncio +{}", "Por anúncio +{}", "Za reklamę +{}", "Reklamla +{}", "Pub +{}", "Con pubblicità +{}"]),
